using System.Windows;
using System.Windows.Controls;
namespace WoWItemEditor;
internal sealed class CreatedQuestsWindow : Window
{
    private readonly DataGrid table=DesignerWindow.Table(("Quest","Title"),("NPC","NpcName"),("NPC ID","NpcId"),("Quest ID","QuestId"),("Status","State"));private readonly TextBlock feedback=DesignerWindow.Text("",12);private bool busy;
    internal CreatedQuestsWindow(CatalogResult catalog){Title="Created quests & NPCs";Width=1100;Height=750;MinWidth=850;MinHeight=500;Background=TooltipView.Brush("#232428");WindowStartupLocation=WindowStartupLocation.CenterOwner;var root=new DockPanel{Margin=new Thickness(20)};Content=root;var top=new StackPanel();DockPanel.SetDock(top,Dock.Top);root.Children.Add(top);top.Children.Add(DesignerWindow.Text("CREATED QUESTS & NPCS",22));top.Children.Add(DesignerWindow.Text("Includes earlier creations. Deletion removes this quest, its copied NPC and spawn. Earned items and character progress remain. Restart the worldserver after deleting. Deleted records stay in this list for reference.",12));var bottom=new StackPanel();DockPanel.SetDock(bottom,Dock.Bottom);root.Children.Add(bottom);bottom.Children.Add(feedback);var actions=new WrapPanel();bottom.Children.Add(actions);DesignerWindow.Button("Edit selected quest",actions).Click+=async(_,_)=>{if(busy||table.SelectedItem is not CreatedQuest entry||entry.State!="Active")return;new QuestEditorWindow(catalog,entry){Owner=this}.ShowDialog();await Load();};DesignerWindow.Button("Refresh",actions).Click+=async(_,_)=>await Load();DesignerWindow.Button("Delete selected NPC + quest…",actions).Click+=async(_,_)=>await Delete();DesignerWindow.Button("Close",actions).Click+=(_,_)=>Close();root.Children.Add(table);Loaded+=async(_,_)=>await Load();Closing+=(_,e)=>e.Cancel=busy;}
    private async Task Load(){try{table.ItemsSource=await CreatedQuests.List();feedback.Text=$"{table.Items.Count} recorded creations";}catch(Exception ex){feedback.Text=ex.Message;}}
    private async Task Delete(){if(busy||table.SelectedItem is not CreatedQuest entry||entry.State!="Active")return;busy=true;try{string expected=await CreatedQuests.Review(entry);var review=new ContentReviewWindow("Delete created NPC + quest",entry.Title,$"NPC {entry.NpcName} ({entry.NpcId}), spawn {entry.SpawnId}, quest {entry.QuestId}\n\n"+"The quest offer, completion dialogue, reward definitions and NPC spawn will be removed.","Remove this created NPC, spawn, quest and their offer/turn-in links. Keep the creation audit marked Deleted. Original templates, reward item definitions and character data remain. A worldserver restart is required."){Owner=this};if(review.ShowDialog()!=true)return;await CreatedQuests.Delete(entry,expected);await Load();feedback.Text="Deleted. Restart the worldserver to remove the cached NPC and quest in game.";}catch(Exception ex){feedback.Text="Deletion failed: "+ex.Message;}finally{busy=false;}}
}
